fn number_f64(row: &Value, field: &str) -> f64 {
    row.get(field)
        .and_then(|value| {
            value
                .as_f64()
                .or_else(|| value.as_i64().map(|value| value as f64))
                .or_else(|| value.as_u64().map(|value| value as f64))
        })
        .unwrap_or_default()
}

