fn collect_settings_files(dir: &Path, files: &mut Vec<PathBuf>) -> Result<(), String> {
    let entries = match fs::read_dir(dir) {
        Ok(entries) => entries,
        Err(err) if err.kind() == std::io::ErrorKind::NotFound => return Ok(()),
        Err(err) => return Err(format!("failed to read {}: {err}", dir.display())),
    };

fn try_prepare_opencode_indexes(db_path: &Path) {
    let Ok(connection) = Connection::open_with_flags(
        db_path,
        OpenFlags::SQLITE_OPEN_READ_WRITE | OpenFlags::SQLITE_OPEN_NO_MUTEX,
    ) else {
        return;
    };

    let _ = connection.execute_batch(
        r#"
        CREATE INDEX IF NOT EXISTS idx_token_usage_message_time_created
        ON message(time_created)
        WHERE data IS NOT NULL;
        "#
    );
}

fn compact_to_iso(value: &str) -> String {
    if value.len() == 8 && value.chars().all(|ch| ch.is_ascii_digit()) {
        format!("{}-{}-{}", &value[0..4], &value[4..6], &value[6..8])
    } else {
        value.to_owned()
    }

